// HSC Business Studies concept & term library
// Definitions written in HSC marking-guideline language, mapped to the same
// topic / sub-topic keys used by SYLLABUS in data.js so results feed the
// existing topic analysis. Fields: id, term, topic, sub, def, formula?, eg?
const GLOSSARY = [

// ================= OPERATIONS =================
// --- Role of operations management ---
{id:"op-operations", term:"Operations", topic:"Operations", sub:"Role of operations management", def:"The business function that transforms inputs into outputs — the goods and/or services a business sells.", eg:"For Qantas the transformation is moving passengers; for Bakers Delight it is baking bread."},
{id:"op-strategic-role", term:"Strategic role of operations", topic:"Operations", sub:"Role of operations management", def:"The contribution operations makes to a business's long-term direction and competitive advantage, mainly through cost leadership and product differentiation."},
{id:"op-cost-leadership", term:"Cost leadership", topic:"Operations", sub:"Role of operations management", def:"A strategy of aiming to have the lowest costs in the market, allowing the business to compete on price while remaining profitable.", eg:"Aldi's limited range and no-frills stores keep unit costs below full-service supermarkets."},
{id:"op-differentiation", term:"Good/service differentiation", topic:"Operations", sub:"Role of operations management", def:"Distinguishing a product from competitors' products by varying its features, quality or service so customers see it as unique.", eg:"Apple differentiates on design and ecosystem rather than price."},
{id:"op-interdependence", term:"Interdependence", topic:"Operations", sub:"Role of operations management", def:"The mutual dependence of the key business functions — operations, marketing, finance and human resources — where a decision in one affects all the others."},
{id:"op-goods-services", term:"Goods and services continuum", topic:"Operations", sub:"Role of operations management", def:"The scale from pure goods (tangible, standardised) through to pure services (intangible, customised), with most businesses sitting somewhere between.", eg:"A restaurant sells a good (the meal) inseparable from a service (the dining experience)."},
{id:"op-standardised", term:"Standardised goods", topic:"Operations", sub:"Role of operations management", def:"Mass-produced goods made to a uniform specification, allowing economies of scale but little customer input."},
{id:"op-customised", term:"Customised goods", topic:"Operations", sub:"Role of operations management", def:"Goods varied to meet an individual customer's requirements, raising unit cost but adding value."},
{id:"op-perishability", term:"Perishability", topic:"Operations", sub:"Role of operations management", def:"A characteristic of services: they cannot be stored for later sale, so unused capacity is lost forever.", eg:"An empty airline seat at take-off can never be sold."},
{id:"op-intangibility", term:"Intangibility", topic:"Operations", sub:"Role of operations management", def:"A characteristic of services: they cannot be seen, touched or tested before purchase, so customers rely on reputation and evidence of quality."},

// --- Influences ---
{id:"op-globalisation", term:"Globalisation (operations)", topic:"Operations", sub:"Influences", def:"The removal of barriers between national economies, giving businesses global markets to sell into and global suppliers and labour to draw on.", eg:"An Australian retailer sourcing garments from Bangladesh and selling online worldwide."},
{id:"op-technology", term:"Technology (as an influence)", topic:"Operations", sub:"Influences", def:"The design, application and use of machinery, systems and processes, which can raise productivity, cut costs and improve quality — but requires capital and retraining."},
{id:"op-quality-expectations", term:"Quality expectations", topic:"Operations", sub:"Influences", def:"Customer assumptions about how well a product will perform, how long it will last and how reliable it will be, which the operations process must be designed to meet."},
{id:"op-cost-competition", term:"Cost-based competition", topic:"Operations", sub:"Influences", def:"Competing by driving costs below rivals so the business can undercut them on price or earn a higher margin at the same price.", eg:"Determined by breaking total costs into fixed and variable and attacking each."},
{id:"op-govt-policies", term:"Government policies (operations)", topic:"Operations", sub:"Influences", def:"Decisions of government — taxation, industrial relations, environmental and trade policy — that change the cost and legality of how a business operates."},
{id:"op-legal-regulation", term:"Legal regulation", topic:"Operations", sub:"Influences", def:"The compulsory laws a business must follow in its operations, covering company registration, work health and safety, fair trading and environmental protection."},
{id:"op-env-sustainability", term:"Environmental sustainability", topic:"Operations", sub:"Influences", def:"Operating so that resource use meets present needs without compromising the ability of future generations to meet theirs.", eg:"Shifting to renewable inputs and closed-loop recycling of packaging."},
{id:"op-csr", term:"Corporate social responsibility", topic:"Operations", sub:"Influences", def:"Open and accountable business behaviour that goes beyond legal compliance to consider the social and environmental consequences of decisions."},
{id:"op-legal-compliance", term:"Legal compliance", topic:"Operations", sub:"Influences", def:"Meeting the minimum standards required by law. It is the floor of acceptable behaviour, whereas ethical responsibility is a voluntary choice to go further."},
{id:"op-triple-bottom", term:"Triple bottom line", topic:"Operations", sub:"Influences", def:"Measuring business performance against economic, social and environmental outcomes rather than profit alone."},
{id:"op-greenwashing", term:"Greenwashing", topic:"Operations", sub:"Influences", def:"Marketing a business or product as environmentally responsible when its actual practices do not support the claim — a breach of ethical responsibility and, increasingly, of consumer law."},

// --- Operations processes ---
{id:"op-inputs", term:"Inputs", topic:"Operations", sub:"Operations processes", def:"The resources used in the process of production, divided into transformed resources and transforming resources."},
{id:"op-transformed", term:"Transformed resources", topic:"Operations", sub:"Operations processes", def:"The inputs that are changed or converted in the operations process: materials, information and customers."},
{id:"op-transforming", term:"Transforming resources", topic:"Operations", sub:"Operations processes", def:"The inputs that carry out the transformation on other resources: human resources and facilities."},
{id:"op-facilities", term:"Facilities", topic:"Operations", sub:"Operations processes", def:"The plant, machinery and premises in which operations occur, and the layout and design decisions attached to them."},
{id:"op-transformation", term:"Transformation process", topic:"Operations", sub:"Operations processes", def:"The conversion of inputs into outputs, shaped by the volume, variety, variation in demand and visibility of the operation."},
{id:"op-volume", term:"Volume (of production)", topic:"Operations", sub:"Operations processes", def:"How much of a product is made. High volume allows repetition, standardisation and lower unit cost."},
{id:"op-variety", term:"Variety (of production)", topic:"Operations", sub:"Operations processes", def:"The range of different products a business makes. High variety raises flexibility but also complexity and cost."},
{id:"op-variation-demand", term:"Variation in demand", topic:"Operations", sub:"Operations processes", def:"The extent to which demand fluctuates over time, requiring the business to build capacity, inventory or a flexible workforce to cope with peaks.", eg:"Ski resorts and ice-cream makers face extreme seasonal variation."},
{id:"op-visibility", term:"Visibility (customer contact)", topic:"Operations", sub:"Operations processes", def:"The degree to which customers can see and experience the transformation process, which raises the importance of staff skills and premises."},
{id:"op-sequencing", term:"Sequencing", topic:"Operations", sub:"Operations processes", def:"Deciding the order in which activities in the operations process are performed."},
{id:"op-scheduling", term:"Scheduling", topic:"Operations", sub:"Operations processes", def:"Deciding the length of time each activity takes and when it will occur — the timetable of production."},
{id:"op-gantt", term:"Gantt chart", topic:"Operations", sub:"Operations processes", def:"A bar chart that maps each task in a project against time, showing what must be done, when, and which tasks overlap."},
{id:"op-cpa", term:"Critical path analysis", topic:"Operations", sub:"Operations processes", def:"A scheduling technique that maps the sequence of dependent tasks and identifies the shortest time in which a project can be completed.", eg:"The critical path is the longest path through the network — any delay on it delays the whole project."},
{id:"op-task-design", term:"Task design", topic:"Operations", sub:"Operations processes", def:"Breaking the work of the transformation process into individual jobs and identifying the skills and activities each requires."},
{id:"op-process-layout", term:"Process layout", topic:"Operations", sub:"Operations processes", def:"Arranging machinery and equipment by function, so products move to the process they need. Suits low-volume, high-variety production."},
{id:"op-product-layout", term:"Product layout", topic:"Operations", sub:"Operations processes", def:"Arranging equipment in the sequence of production so the product flows along a line. Suits high-volume, standardised output."},
{id:"op-fixed-position", term:"Fixed position layout", topic:"Operations", sub:"Operations processes", def:"A layout where the product stays in one place and resources are brought to it, used where the output is too large to move.", eg:"Shipbuilding and major construction projects."},
{id:"op-monitoring", term:"Monitoring", topic:"Operations", sub:"Operations processes", def:"Measuring actual performance against pre-determined targets by collecting data on key performance indicators."},
{id:"op-control", term:"Control", topic:"Operations", sub:"Operations processes", def:"Assessing performance against targets and taking corrective action where variance occurs."},
{id:"op-improvement", term:"Continuous improvement", topic:"Operations", sub:"Operations processes", def:"An ongoing commitment to making small, incremental gains in the operations process rather than waiting for major overhauls."},
{id:"op-outputs", term:"Outputs", topic:"Operations", sub:"Operations processes", def:"The end result of the transformation process — the goods and/or services delivered to the customer."},
{id:"op-customer-service", term:"Customer service", topic:"Operations", sub:"Operations processes", def:"How well a business meets and exceeds the expectations of customers in delivering its product, including responsiveness and after-sales support."},
{id:"op-warranty", term:"Warranty", topic:"Operations", sub:"Operations processes", def:"A promise by the business to repair, replace or refund a faulty product, acting as both a quality signal and a source of feedback on defects."},

// --- Operations strategies ---
{id:"op-perf-objectives", term:"Performance objectives", topic:"Operations", sub:"Operations strategies", def:"The goals that relate to specific aspects of the operations process: quality, speed, dependability, flexibility, customisation and cost."},
{id:"op-po-quality", term:"Quality (performance objective)", topic:"Operations", sub:"Operations strategies", def:"How well a product meets its intended purpose and customer expectations, measured through design, conformance and fitness for purpose."},
{id:"op-po-speed", term:"Speed (performance objective)", topic:"Operations", sub:"Operations strategies", def:"The time taken for the production and distribution of a product, measured from order to delivery."},
{id:"op-po-dependability", term:"Dependability", topic:"Operations", sub:"Operations strategies", def:"How consistent and reliable a business's products are, and whether it delivers what it promised when it promised."},
{id:"op-po-flexibility", term:"Flexibility (performance objective)", topic:"Operations", sub:"Operations strategies", def:"How quickly the operations process can adjust to changes in the market, in volume or in product design."},
{id:"op-po-customisation", term:"Customisation", topic:"Operations", sub:"Operations strategies", def:"Creating individualised products to meet the specific needs of particular customers."},
{id:"op-po-cost", term:"Cost (performance objective)", topic:"Operations", sub:"Operations strategies", def:"Minimising the expense of the transformation process so the business can compete on price or widen its margin."},
{id:"op-npd", term:"New product design and development", topic:"Operations", sub:"Operations strategies", def:"Creating or redesigning products so they meet changing customer needs, extend the product life cycle and sustain competitive advantage."},
{id:"op-scm", term:"Supply chain management", topic:"Operations", sub:"Operations strategies", def:"Integrating and managing the flow of supplies, information and finances from raw material through to the end customer, to cut cost and raise reliability."},
{id:"op-logistics", term:"Logistics", topic:"Operations", sub:"Operations strategies", def:"The distribution element of the supply chain: transport, warehousing and materials handling that move product to the customer."},
{id:"op-ecommerce", term:"E-commerce", topic:"Operations", sub:"Operations strategies", def:"Buying and selling of goods, services and information over the internet, allowing 24-hour trading and direct links between business and supplier."},
{id:"op-global-sourcing", term:"Global sourcing", topic:"Operations", sub:"Operations strategies", def:"Buying supplies without being constrained by national borders, to access lower prices or capabilities not available domestically."},
{id:"op-outsourcing", term:"Outsourcing", topic:"Operations", sub:"Operations strategies", def:"Using an external provider to perform a business activity that could be done in-house, in order to cut cost or access specialist expertise."},
{id:"op-leading-edge", term:"Leading edge technology", topic:"Operations", sub:"Operations strategies", def:"The most advanced technology available at a point in time. It offers competitive advantage but is expensive and carries the risk of being unproven."},
{id:"op-established-tech", term:"Established technology", topic:"Operations", sub:"Operations strategies", def:"Technology that has been widely adopted and proven reliable. It is cheaper and lower risk, but offers no advantage over competitors using the same tools."},
{id:"op-cad", term:"Computer-aided design (CAD)", topic:"Operations", sub:"Operations strategies", def:"Software that creates and tests product designs in three dimensions before physical prototypes are built, cutting development time and cost."},
{id:"op-cam", term:"Computer-aided manufacturing (CAM)", topic:"Operations", sub:"Operations strategies", def:"Software that controls machinery in the production process, raising precision and allowing production to run with less labour."},
{id:"op-inventory-mgmt", term:"Inventory management", topic:"Operations", sub:"Operations strategies", def:"Controlling the level of stock held so the business can meet demand without tying up excessive capital in unsold goods."},
{id:"op-jit", term:"Just-in-time (JIT)", topic:"Operations", sub:"Operations strategies", def:"An inventory strategy where supplies arrive exactly when required for production, minimising holding costs but leaving no buffer against supply disruption."},
{id:"op-lifo", term:"LIFO (last-in-first-out)", topic:"Operations", sub:"Operations strategies", def:"An inventory valuation method that assumes the most recently purchased stock is used or sold first."},
{id:"op-fifo", term:"FIFO (first-in-first-out)", topic:"Operations", sub:"Operations strategies", def:"An inventory valuation method that assumes the oldest stock is used or sold first — appropriate for perishable goods."},
{id:"op-quality-mgmt", term:"Quality management", topic:"Operations", sub:"Operations strategies", def:"The processes a business uses to ensure its products consistently meet customer expectations, through quality control, quality assurance and quality improvement."},
{id:"op-quality-control", term:"Quality control", topic:"Operations", sub:"Operations strategies", def:"Inspection at various points in the production process to identify defects after they occur, so faulty output does not reach the customer."},
{id:"op-quality-assurance", term:"Quality assurance", topic:"Operations", sub:"Operations strategies", def:"Certifying that a set of external standards is being met throughout the process, so defects are prevented rather than detected.", eg:"ISO 9000 certification is the common international benchmark."},
{id:"op-quality-improvement", term:"Quality improvement", topic:"Operations", sub:"Operations strategies", def:"An ongoing commitment by all staff to raising quality, often through total quality management and employee empowerment."},
{id:"op-tqm", term:"Total quality management", topic:"Operations", sub:"Operations strategies", def:"A whole-of-business approach in which every employee takes responsibility for quality and continuous improvement rather than leaving it to inspectors."},
{id:"op-resistance-change", term:"Resistance to change", topic:"Operations", sub:"Operations strategies", def:"Opposition from staff or management to a proposed change, arising from financial cost, fear of job loss, or simple inertia."},
{id:"op-inertia", term:"Inertia", topic:"Operations", sub:"Operations strategies", def:"A deep reluctance within a business to depart from established ways of doing things, even when those ways are no longer effective."},
{id:"op-redundancy", term:"Redundancy payment", topic:"Operations", sub:"Operations strategies", def:"Compensation paid to an employee whose position is abolished, a major financial cost of restructuring operations."},
{id:"op-economies-scale", term:"Economies of scale", topic:"Operations", sub:"Operations strategies", def:"The fall in average cost per unit that occurs as the scale of production rises and fixed costs are spread more thinly.", formula:"Average cost = total cost ÷ units produced"},
{id:"op-scanning-learning", term:"Scanning and learning", topic:"Operations", sub:"Operations strategies", def:"Continually examining global markets, competitors and technologies so the business can adopt better practice rather than invent it from scratch."},
{id:"op-rd", term:"Research and development", topic:"Operations", sub:"Operations strategies", def:"Systematic investigation aimed at creating new products or improving processes, a key source of long-term competitive advantage."},
{id:"op-lean", term:"Lean production", topic:"Operations", sub:"Operations strategies", def:"An approach that systematically removes waste from every stage of the operations process while maintaining or improving quality."},
{id:"op-capacity", term:"Capacity", topic:"Operations", sub:"Operations strategies", def:"The maximum output a business can produce with its current facilities and resources in a given period."},

// ================= MARKETING =================
// --- Role of marketing ---
{id:"mk-marketing", term:"Marketing", topic:"Marketing", sub:"Role of marketing", def:"The process of identifying, anticipating and satisfying customer needs and wants profitably."},
{id:"mk-strategic-role", term:"Strategic role of marketing", topic:"Marketing", sub:"Role of marketing", def:"Marketing's contribution to achieving business goals by creating and holding a place in the market that competitors find hard to take."},
{id:"mk-production-approach", term:"Production approach", topic:"Marketing", sub:"Role of marketing", def:"An early business orientation focused on producing as much as possible as cheaply as possible, on the assumption that anything made will sell."},
{id:"mk-selling-approach", term:"Selling approach", topic:"Marketing", sub:"Role of marketing", def:"A business orientation focused on aggressive promotion and personal selling to shift what has already been produced."},
{id:"mk-marketing-approach", term:"Marketing approach", topic:"Marketing", sub:"Role of marketing", def:"A business orientation that starts with customer needs and designs the product to satisfy them, rather than selling what the business happens to make."},
{id:"mk-resource-market", term:"Resource market", topic:"Marketing", sub:"Role of marketing", def:"A market in which businesses buy the raw materials, land, labour and capital used in production."},
{id:"mk-industrial-market", term:"Industrial market", topic:"Marketing", sub:"Role of marketing", def:"A market in which businesses buy goods and services to use in producing other goods and services."},
{id:"mk-intermediate-market", term:"Intermediate market", topic:"Marketing", sub:"Role of marketing", def:"A market of wholesalers and retailers who buy finished goods in order to resell them at a profit."},
{id:"mk-consumer-market", term:"Consumer market", topic:"Marketing", sub:"Role of marketing", def:"A market of individuals who buy goods and services for their own personal use rather than resale."},
{id:"mk-mass-market", term:"Mass market", topic:"Marketing", sub:"Role of marketing", def:"A market approach that treats all buyers as one group and offers a single marketing mix to the whole market."},
{id:"mk-niche-market", term:"Niche market", topic:"Marketing", sub:"Role of marketing", def:"A narrowly defined segment of a market with distinctive needs, served by a specialised marketing mix.", eg:"Gluten-free bakery products or left-handed sporting equipment."},

// --- Influences on marketing ---
{id:"mk-psychological", term:"Psychological influences", topic:"Marketing", sub:"Influences on marketing", def:"Factors within the individual that shape buying behaviour — perception, motives, attitudes, personality and learning."},
{id:"mk-sociocultural", term:"Sociocultural influences", topic:"Marketing", sub:"Influences on marketing", def:"Forces from the groups a consumer belongs to — family, peers, social class and culture — that shape what and how they buy."},
{id:"mk-economic-influence", term:"Economic influences (marketing)", topic:"Marketing", sub:"Influences on marketing", def:"The state of the economy — boom or recession, interest rates, unemployment — which changes consumers' willingness and ability to spend."},
{id:"mk-govt-influence", term:"Government influences (marketing)", topic:"Marketing", sub:"Influences on marketing", def:"Laws and regulations that constrain marketing conduct, protecting consumers from unfair, misleading or unsafe practices."},
{id:"mk-accc", term:"ACCC", topic:"Marketing", sub:"Influences on marketing", def:"The Australian Competition and Consumer Commission — the national regulator that enforces competition and consumer law, including against misleading advertising."},
{id:"mk-deceptive-advertising", term:"Deceptive and misleading advertising", topic:"Marketing", sub:"Influences on marketing", def:"Promotion that creates a false impression about a product's price, quality, value or origin. It is illegal under Australian Consumer Law."},
{id:"mk-price-discrimination", term:"Price discrimination", topic:"Marketing", sub:"Influences on marketing", def:"Charging different prices to different buyers for the same good where the difference is not justified by cost — unlawful where it substantially lessens competition."},
{id:"mk-implied-conditions", term:"Implied conditions", topic:"Marketing", sub:"Influences on marketing", def:"Unwritten terms automatically part of every consumer contract, such as that goods are of acceptable quality and fit for their stated purpose."},
{id:"mk-warranties", term:"Warranties (consumer law)", topic:"Marketing", sub:"Influences on marketing", def:"Promises by the seller about the quality, performance or servicing of a product, enforceable in addition to consumer guarantees."},
{id:"mk-resale-price", term:"Resale price maintenance", topic:"Marketing", sub:"Influences on marketing", def:"A supplier pressuring a retailer not to sell below a specified price. It is prohibited because it removes price competition."},
{id:"mk-sugging", term:"Sugging", topic:"Marketing", sub:"Influences on marketing", def:"Selling under the guise of research — pretending to conduct a survey in order to make a sale. An unethical marketing practice."},
{id:"mk-ethical-marketing", term:"Ethical marketing", topic:"Marketing", sub:"Influences on marketing", def:"Marketing conducted with truth, accuracy and good taste, avoiding products that damage health and engaging in fair competition."},

// --- Marketing process ---
{id:"mk-situational-analysis", term:"Situational analysis", topic:"Marketing", sub:"Marketing process", def:"Assessing where a business currently stands in its market before setting objectives, commonly through SWOT analysis and product life cycle review."},
{id:"mk-swot", term:"SWOT analysis", topic:"Marketing", sub:"Marketing process", def:"An audit of a business's internal Strengths and Weaknesses and its external Opportunities and Threats."},
{id:"mk-plc", term:"Product life cycle", topic:"Marketing", sub:"Marketing process", def:"The stages a product passes through from launch to withdrawal: introduction, growth, maturity and decline, each requiring a different marketing mix."},
{id:"mk-market-research", term:"Market research", topic:"Marketing", sub:"Marketing process", def:"The systematic collection, recording and analysis of data about a market, to reduce the risk in marketing decisions."},
{id:"mk-primary-data", term:"Primary data", topic:"Marketing", sub:"Marketing process", def:"Information collected first-hand for the specific research purpose, through surveys, observation or experiments. Accurate but costly."},
{id:"mk-secondary-data", term:"Secondary data", topic:"Marketing", sub:"Marketing process", def:"Information already collected for another purpose, such as ABS statistics or internal sales records. Cheap and fast but may be dated or not quite on point."},
{id:"mk-market-objectives", term:"Market objectives", topic:"Marketing", sub:"Marketing process", def:"Specific, measurable targets the marketing plan is designed to achieve, such as increasing market share by a set percentage within a set time."},
{id:"mk-market-share", term:"Market share", topic:"Marketing", sub:"Marketing process", def:"A business's sales expressed as a proportion of total industry sales.", formula:"Market share = business sales ÷ total market sales × 100"},
{id:"mk-target-market", term:"Target market", topic:"Marketing", sub:"Marketing process", def:"The specific group of customers a business directs its marketing mix towards."},
{id:"mk-financial-forecast", term:"Financial forecast", topic:"Marketing", sub:"Marketing process", def:"A projection of the revenue a marketing strategy will generate and the costs it will incur, used to judge whether the plan is viable."},
{id:"mk-marketing-plan", term:"Marketing plan", topic:"Marketing", sub:"Marketing process", def:"A written document setting out marketing objectives and the strategies, budget and timeline for achieving them."},

// --- Marketing strategies ---
{id:"mk-segmentation", term:"Market segmentation", topic:"Marketing", sub:"Marketing strategies", def:"Dividing the total market into subgroups of consumers with shared characteristics so each can be targeted with a tailored mix.", eg:"Segmented by demographics, geography, psychographics or behaviour."},
{id:"mk-product-diff", term:"Product/service differentiation", topic:"Marketing", sub:"Marketing strategies", def:"Distinguishing a product from competing products in the mind of the consumer, through features, quality, service or image."},
{id:"mk-positioning", term:"Positioning", topic:"Marketing", sub:"Marketing strategies", def:"The place a product occupies in the consumer's mind relative to competitors, particularly on price and quality."},
{id:"mk-marketing-mix", term:"Marketing mix", topic:"Marketing", sub:"Marketing strategies", def:"The combination of controllable elements a business uses to satisfy its target market — product, price, promotion and place, extended for services to people, processes and physical evidence."},
{id:"mk-branding", term:"Branding", topic:"Marketing", sub:"Marketing strategies", def:"A name, term, symbol or design that identifies a product and differentiates it from competitors, building recognition and loyalty."},
{id:"mk-brand-loyalty", term:"Brand loyalty", topic:"Marketing", sub:"Marketing strategies", def:"The degree to which consumers consistently repurchase one brand rather than switching, allowing a price premium and reducing marketing cost."},
{id:"mk-packaging", term:"Packaging", topic:"Marketing", sub:"Marketing strategies", def:"The container and wrapping of a product, which protects it, carries required information and acts as a point-of-sale promotional tool."},
{id:"mk-cost-pricing", term:"Cost-based pricing", topic:"Marketing", sub:"Marketing strategies", def:"Setting price by adding a mark-up to the cost of producing the product.", formula:"Price = cost + mark-up"},
{id:"mk-market-pricing", term:"Market-based pricing", topic:"Marketing", sub:"Marketing strategies", def:"Setting price according to the interaction of supply and demand, which may mean charging what the market will bear."},
{id:"mk-competition-pricing", term:"Competition-based pricing", topic:"Marketing", sub:"Marketing strategies", def:"Setting price relative to competitors' prices — below, equal to, or above them depending on the desired position."},
{id:"mk-skimming", term:"Price skimming", topic:"Marketing", sub:"Marketing strategies", def:"Charging the highest possible price during the introduction stage, when the product is novel and competition is limited.", eg:"New smartphone models launch high and fall in price within months."},
{id:"mk-penetration", term:"Price penetration", topic:"Marketing", sub:"Marketing strategies", def:"Charging a deliberately low price on launch to gain market share quickly, then raising it once customers are established."},
{id:"mk-loss-leader", term:"Loss leader", topic:"Marketing", sub:"Marketing strategies", def:"Selling a product at or below cost to draw customers into the store, in the expectation they will buy profitable items as well."},
{id:"mk-price-points", term:"Price points", topic:"Marketing", sub:"Marketing strategies", def:"Selling a range of products at a limited number of set prices, simplifying the choice for consumers.", eg:"A $2 shop, or a menu with $15, $25 and $35 tiers."},
{id:"mk-price-quality", term:"Price and quality interaction", topic:"Marketing", sub:"Marketing strategies", def:"The tendency of consumers to infer quality from price, so that a low price can signal inferior goods and a high price can signal prestige."},
{id:"mk-promotion-mix", term:"Promotion mix", topic:"Marketing", sub:"Marketing strategies", def:"The combination of advertising, personal selling and relationship marketing, sales promotions, and publicity and public relations used to communicate with the target market."},
{id:"mk-advertising", term:"Advertising", topic:"Marketing", sub:"Marketing strategies", def:"Paid, non-personal communication through mass media designed to inform and persuade a target audience."},
{id:"mk-personal-selling", term:"Personal selling", topic:"Marketing", sub:"Marketing strategies", def:"Direct contact between a salesperson and a prospective buyer, allowing the message to be tailored and objections answered."},
{id:"mk-relationship-marketing", term:"Relationship marketing", topic:"Marketing", sub:"Marketing strategies", def:"Developing long-term, cost-effective links with individual customers for mutual benefit, rather than pursuing one-off transactions."},
{id:"mk-sales-promotion", term:"Sales promotion", topic:"Marketing", sub:"Marketing strategies", def:"Short-term activity that adds extra value to induce an immediate purchase, such as coupons, samples, competitions and loyalty points."},
{id:"mk-publicity", term:"Publicity", topic:"Marketing", sub:"Marketing strategies", def:"Free media coverage of a business or its products, which carries high credibility but cannot be directly controlled."},
{id:"mk-public-relations", term:"Public relations", topic:"Marketing", sub:"Marketing strategies", def:"Planned activity designed to create and maintain a favourable public image of the business, including sponsorship and community programs."},
{id:"mk-opinion-leader", term:"Opinion leader", topic:"Marketing", sub:"Marketing strategies", def:"A person whose views influence the buying behaviour of others, used by marketers to spread a message credibly."},
{id:"mk-word-of-mouth", term:"Word of mouth", topic:"Marketing", sub:"Marketing strategies", def:"Communication about a product passed informally between consumers. It is highly persuasive and, online, extremely fast."},
{id:"mk-distribution-channel", term:"Distribution channel", topic:"Marketing", sub:"Marketing strategies", def:"The route a product takes from producer to consumer, possibly via wholesalers, retailers or agents."},
{id:"mk-intensive-dist", term:"Intensive distribution", topic:"Marketing", sub:"Marketing strategies", def:"Placing a product in as many outlets as possible, appropriate for low-cost convenience goods."},
{id:"mk-selective-dist", term:"Selective distribution", topic:"Marketing", sub:"Marketing strategies", def:"Using a moderate number of carefully chosen outlets, balancing coverage with control over how the product is presented."},
{id:"mk-exclusive-dist", term:"Exclusive distribution", topic:"Marketing", sub:"Marketing strategies", def:"Granting one outlet the sole right to sell the product in an area, used to protect a prestige image."},
{id:"mk-physical-distribution", term:"Physical distribution", topic:"Marketing", sub:"Marketing strategies", def:"The transport, warehousing and inventory activities that physically move a product to the point of sale."},
{id:"mk-people", term:"People (services marketing)", topic:"Marketing", sub:"Marketing strategies", def:"The staff who deliver a service and whose skills, attitude and appearance form part of the customer's judgement of quality."},
{id:"mk-processes", term:"Processes (services marketing)", topic:"Marketing", sub:"Marketing strategies", def:"The systems and procedures by which a service is delivered, which shape how convenient and consistent the experience feels."},
{id:"mk-physical-evidence", term:"Physical evidence", topic:"Marketing", sub:"Marketing strategies", def:"The tangible cues that signal service quality where the service itself is intangible — premises, uniforms, equipment and documentation."},
{id:"mk-emarketing", term:"E-marketing", topic:"Marketing", sub:"Marketing strategies", def:"Using the internet and digital channels to market products, enabling targeting, personalisation and measurement not possible in mass media."},
{id:"mk-global-branding", term:"Global branding", topic:"Marketing", sub:"Marketing strategies", def:"Using the same brand name, image and positioning in every market a business operates in, building worldwide recognition."},
{id:"mk-standardisation", term:"Standardisation (global marketing)", topic:"Marketing", sub:"Marketing strategies", def:"Selling the same product with the same marketing mix in every country, which minimises cost but ignores local differences."},
{id:"mk-customisation-global", term:"Customisation (global marketing)", topic:"Marketing", sub:"Marketing strategies", def:"Adapting the product or marketing mix to the tastes, laws and conditions of each national market."},
{id:"mk-global-pricing", term:"Global pricing", topic:"Marketing", sub:"Marketing strategies", def:"Deciding how prices will be set across markets — customised for each, market-centred, or a single standardised worldwide price."},
{id:"mk-competitive-positioning", term:"Competitive positioning", topic:"Marketing", sub:"Marketing strategies", def:"Establishing how a global brand will be perceived against local and international rivals in each market it enters."},

// ================= FINANCE =================
// --- Role of financial management ---
{id:"fi-financial-mgmt", term:"Financial management", topic:"Finance", sub:"Role of financial management", def:"Planning and monitoring a business's financial resources so it can meet its objectives and obligations."},
{id:"fi-strategic-role", term:"Strategic role of financial management", topic:"Finance", sub:"Role of financial management", def:"Ensuring the business has the funds it needs, at acceptable cost and risk, to pursue its long-term goals."},
{id:"fi-profitability", term:"Profitability", topic:"Finance", sub:"Role of financial management", def:"The ability of a business to maximise profit relative to sales, assets or equity.", formula:"Net profit ratio = net profit ÷ sales"},
{id:"fi-growth", term:"Growth (financial objective)", topic:"Finance", sub:"Role of financial management", def:"The ability of a business to increase in size over the long term, measured through sales, assets or market share."},
{id:"fi-efficiency", term:"Efficiency (financial objective)", topic:"Finance", sub:"Role of financial management", def:"How well a business uses its resources to achieve its objectives, particularly how quickly it converts assets into sales and receivables into cash."},
{id:"fi-liquidity", term:"Liquidity", topic:"Finance", sub:"Role of financial management", def:"The ability of a business to pay its short-term debts as they fall due, from its current assets.", formula:"Current ratio = current assets ÷ current liabilities"},
{id:"fi-solvency", term:"Solvency", topic:"Finance", sub:"Role of financial management", def:"The ability of a business to meet its long-term financial commitments — its capacity to survive beyond the next twelve months.", formula:"Gearing = total liabilities ÷ total equity"},
{id:"fi-short-term-obj", term:"Short-term financial objectives", topic:"Finance", sub:"Role of financial management", def:"Tactical financial targets set for the coming budget period, usually about cash flow, cost control and liquidity."},
{id:"fi-long-term-obj", term:"Long-term financial objectives", topic:"Finance", sub:"Role of financial management", def:"Strategic financial targets set for several years ahead, usually about growth, solvency and return on equity."},

// --- Influences on financial management ---
{id:"fi-internal-finance", term:"Internal sources of finance", topic:"Finance", sub:"Influences on financial management", def:"Funds generated from within the business, principally retained profits, which carry no interest cost and no loss of control."},
{id:"fi-retained-profits", term:"Retained profits", topic:"Finance", sub:"Influences on financial management", def:"The portion of net profit kept in the business rather than distributed to owners, and reinvested as a cheap source of finance."},
{id:"fi-external-finance", term:"External sources of finance", topic:"Finance", sub:"Influences on financial management", def:"Funds raised from outside the business, split into debt (borrowed) and equity (ownership) finance."},
{id:"fi-debt-finance", term:"Debt finance", topic:"Finance", sub:"Influences on financial management", def:"Funds borrowed from external sources that must be repaid with interest. It is tax deductible and does not dilute ownership, but raises risk."},
{id:"fi-equity-finance", term:"Equity finance", topic:"Finance", sub:"Influences on financial management", def:"Funds contributed by the owners of the business. It carries no repayment obligation but dilutes control and expects a return."},
{id:"fi-overdraft", term:"Bank overdraft", topic:"Finance", sub:"Influences on financial management", def:"An arrangement allowing a business to overdraw its account to an agreed limit, used to cover short-term cash shortfalls."},
{id:"fi-commercial-bills", term:"Commercial bills", topic:"Finance", sub:"Influences on financial management", def:"Short-term loans of $100,000 or more, issued for 30 to 180 days, where the borrower agrees to repay the face value at maturity."},
{id:"fi-factoring", term:"Factoring", topic:"Finance", sub:"Influences on financial management", def:"Selling accounts receivable to a finance company at a discount for immediate cash, improving liquidity but reducing the amount collected."},
{id:"fi-mortgage", term:"Mortgage", topic:"Finance", sub:"Influences on financial management", def:"A long-term loan secured against property, where the lender can take the asset if repayments are not made."},
{id:"fi-debentures", term:"Debentures", topic:"Finance", sub:"Influences on financial management", def:"Loans to a company for a fixed rate of return over a fixed period, secured against the company's assets."},
{id:"fi-unsecured-notes", term:"Unsecured notes", topic:"Finance", sub:"Influences on financial management", def:"Loans to a company for a set period that are not backed by any collateral, so they carry the highest risk and interest rate."},
{id:"fi-leasing", term:"Leasing", topic:"Finance", sub:"Influences on financial management", def:"Paying for the use of an asset owned by another party, avoiding a large capital outlay and keeping the asset off the balance sheet."},
{id:"fi-ordinary-shares", term:"Ordinary shares", topic:"Finance", sub:"Influences on financial management", def:"Units of ownership in a company that entitle the holder to dividends and voting rights, and to residual assets on winding up."},
{id:"fi-new-issue", term:"New issue", topic:"Finance", sub:"Influences on financial management", def:"Shares offered to the public for the first time, raising equity capital for the company."},
{id:"fi-rights-issue", term:"Rights issue", topic:"Finance", sub:"Influences on financial management", def:"The privilege granted to existing shareholders to buy new shares, usually at a discount, in proportion to their current holding."},
{id:"fi-placement", term:"Placement", topic:"Finance", sub:"Influences on financial management", def:"The allocation of new shares to selected institutional investors rather than to the general public, allowing capital to be raised quickly."},
{id:"fi-spp", term:"Share purchase plan", topic:"Finance", sub:"Influences on financial management", def:"An offer to existing shareholders to buy additional shares up to a capped value without brokerage."},
{id:"fi-private-equity", term:"Private equity", topic:"Finance", sub:"Influences on financial management", def:"Capital raised from private investors rather than a public market, in exchange for a share of ownership."},
{id:"fi-banks", term:"Banks", topic:"Finance", sub:"Influences on financial management", def:"The main providers of debt finance to business, accepting deposits and lending at a margin above their cost of funds."},
{id:"fi-investment-banks", term:"Investment banks", topic:"Finance", sub:"Influences on financial management", def:"Institutions that provide advice and finance to large businesses on share issues, mergers and takeovers."},
{id:"fi-super-funds", term:"Superannuation funds", topic:"Finance", sub:"Influences on financial management", def:"Institutions that invest compulsory retirement contributions, and in doing so are among the largest sources of investment capital in Australia."},
{id:"fi-unit-trusts", term:"Unit trusts", topic:"Finance", sub:"Influences on financial management", def:"Funds that pool money from many small investors and invest it in a portfolio of assets managed by professionals."},
{id:"fi-asx", term:"Australian Securities Exchange", topic:"Finance", sub:"Influences on financial management", def:"The primary market for buying and selling shares in Australian listed companies, providing companies with access to equity capital."},
{id:"fi-asic", term:"ASIC", topic:"Finance", sub:"Influences on financial management", def:"The Australian Securities and Investments Commission — the regulator that enforces company and financial services law and monitors corporate disclosure."},
{id:"fi-company-tax", term:"Company taxation", topic:"Finance", sub:"Influences on financial management", def:"Tax levied on company profits, which reduces funds available for reinvestment and influences financing and dividend decisions."},
{id:"fi-economic-outlook", term:"Economic outlook", topic:"Finance", sub:"Influences on financial management", def:"Expected conditions in the domestic and world economy, which shape the availability and cost of finance and the demand for output."},
{id:"fi-availability-funds", term:"Availability of funds", topic:"Finance", sub:"Influences on financial management", def:"The ease with which a business can access finance in international markets, which tightens sharply during a credit squeeze."},
{id:"fi-interest-rates", term:"Interest rates", topic:"Finance", sub:"Influences on financial management", def:"The cost of borrowing money. Higher rates raise the cost of debt finance and reduce the viability of investment projects."},

// --- Processes of financial management ---
{id:"fi-budget", term:"Budget", topic:"Finance", sub:"Processes of financial management", def:"A financial plan that sets out expected revenues and expenses for a future period, providing a benchmark for control."},
{id:"fi-record-systems", term:"Record systems", topic:"Finance", sub:"Processes of financial management", def:"The mechanisms by which financial data is collected, recorded and reported, ensuring information is accurate and available when decisions are made."},
{id:"fi-financial-risk", term:"Financial risk", topic:"Finance", sub:"Processes of financial management", def:"The risk that a business cannot cover its financial obligations, which rises as the proportion of debt in the capital structure rises."},
{id:"fi-financial-controls", term:"Financial controls", topic:"Finance", sub:"Processes of financial management", def:"Policies and procedures that safeguard assets and ensure records are accurate, such as separation of duties and authorisation limits."},
{id:"fi-matching-principle", term:"Matching the terms and source of finance", topic:"Finance", sub:"Processes of financial management", def:"Funding short-term assets with short-term finance and long-term assets with long-term finance, so repayment timing matches the return the asset generates."},
{id:"fi-cash-flow-statement", term:"Cash flow statement", topic:"Finance", sub:"Processes of financial management", def:"A statement showing the movement of cash receipts and payments over a period, classified into operating, investing and financing activities."},
{id:"fi-income-statement", term:"Income statement", topic:"Finance", sub:"Processes of financial management", def:"A statement summarising revenue earned and expenses incurred over a period to show the resulting profit or loss.", formula:"Net profit = gross profit − expenses"},
{id:"fi-balance-sheet", term:"Balance sheet", topic:"Finance", sub:"Processes of financial management", def:"A statement of a business's assets, liabilities and owner's equity at a single point in time.", formula:"Assets = liabilities + owner's equity"},
{id:"fi-current-ratio", term:"Current ratio", topic:"Finance", sub:"Processes of financial management", def:"A liquidity ratio measuring the capacity of current assets to cover current liabilities.", formula:"Current ratio = current assets ÷ current liabilities"},
{id:"fi-gearing", term:"Gearing (debt to equity)", topic:"Finance", sub:"Processes of financial management", def:"A solvency ratio measuring the proportion of the business funded by debt rather than equity. Higher gearing means higher risk and higher potential return.", formula:"Debt to equity = total liabilities ÷ total equity"},
{id:"fi-gross-profit-ratio", term:"Gross profit ratio", topic:"Finance", sub:"Processes of financial management", def:"A profitability ratio showing what proportion of each sales dollar is left after paying for the goods sold.", formula:"Gross profit ratio = gross profit ÷ sales"},
{id:"fi-net-profit-ratio", term:"Net profit ratio", topic:"Finance", sub:"Processes of financial management", def:"A profitability ratio showing what proportion of each sales dollar remains as profit after all expenses.", formula:"Net profit ratio = net profit ÷ sales"},
{id:"fi-roe", term:"Return on equity ratio", topic:"Finance", sub:"Processes of financial management", def:"A profitability ratio showing how effectively the owners' funds have been used to generate profit.", formula:"Return on equity = net profit ÷ total equity"},
{id:"fi-expense-ratio", term:"Expense ratio", topic:"Finance", sub:"Processes of financial management", def:"An efficiency ratio showing what proportion of sales revenue is absorbed by expenses.", formula:"Expense ratio = total expenses ÷ sales"},
{id:"fi-art", term:"Accounts receivable turnover ratio", topic:"Finance", sub:"Processes of financial management", def:"An efficiency ratio measuring how quickly a business collects the money owed to it by credit customers.", formula:"Accounts receivable turnover = sales ÷ accounts receivable"},
{id:"fi-comparative-ratio", term:"Comparative ratio analysis", topic:"Finance", sub:"Processes of financial management", def:"Judging a ratio by comparing it over different time periods, against industry standards, or with similar businesses — because a ratio alone means little."},
{id:"fi-normalised-earnings", term:"Normalised earnings", topic:"Finance", sub:"Processes of financial management", def:"Profit adjusted to remove one-off items, which can be used legitimately to show underlying performance or misleadingly to flatter results."},
{id:"fi-capitalising-expenses", term:"Capitalising expenses", topic:"Finance", sub:"Processes of financial management", def:"Recording an expense as an asset on the balance sheet rather than a cost on the income statement, which overstates both profit and assets."},
{id:"fi-valuing-assets", term:"Valuing assets", topic:"Finance", sub:"Processes of financial management", def:"The judgement involved in placing a value on assets, especially intangibles like goodwill, which makes reported asset figures subjective."},
{id:"fi-timing-issues", term:"Timing issues", topic:"Finance", sub:"Processes of financial management", def:"The distortion caused by recording transactions in one period rather than another, so reports capture a favourable moment rather than the trend."},
{id:"fi-notes-statements", term:"Notes to the financial statements", topic:"Finance", sub:"Processes of financial management", def:"Explanatory detail attached to the statements. Material information disclosed only in the notes is easily overlooked by users."},
{id:"fi-audit", term:"Audit", topic:"Finance", sub:"Processes of financial management", def:"An independent examination of financial records to verify that they present a true and fair view of the business's position."},

// --- Financial management strategies ---
{id:"fi-cash-flow-mgmt", term:"Cash flow management", topic:"Finance", sub:"Financial management strategies", def:"Ensuring sufficient cash is available to meet payments as they fall due, by controlling the timing of receipts and payments."},
{id:"fi-distribution-payments", term:"Distribution of payments", topic:"Finance", sub:"Financial management strategies", def:"Spreading large payments evenly across the year so cash outflows do not cluster and create a shortfall."},
{id:"fi-early-discount", term:"Discounts for early payment", topic:"Finance", sub:"Financial management strategies", def:"Offering credit customers a reduction for paying quickly, which accelerates cash inflow at the cost of some revenue."},
{id:"fi-working-capital", term:"Working capital", topic:"Finance", sub:"Financial management strategies", def:"The funds available for the short-term financial commitments of a business.", formula:"Working capital = current assets − current liabilities"},
{id:"fi-current-assets", term:"Current assets", topic:"Finance", sub:"Financial management strategies", def:"Resources the business expects to convert into cash within twelve months: cash, receivables and inventories."},
{id:"fi-current-liabilities", term:"Current liabilities", topic:"Finance", sub:"Financial management strategies", def:"Debts the business must settle within twelve months: payables, short-term loans and overdrafts."},
{id:"fi-receivables", term:"Accounts receivable", topic:"Finance", sub:"Financial management strategies", def:"Money owed to the business by customers who bought on credit. Slow collection ties up cash and threatens liquidity."},
{id:"fi-payables", term:"Accounts payable", topic:"Finance", sub:"Financial management strategies", def:"Money the business owes to suppliers for goods bought on credit — an interest-free source of short-term finance if managed well."},
{id:"fi-sale-leaseback", term:"Sale and lease back", topic:"Finance", sub:"Financial management strategies", def:"Selling an owned asset and immediately leasing it back, which releases cash while retaining use of the asset."},
{id:"fi-cost-controls", term:"Cost controls", topic:"Finance", sub:"Financial management strategies", def:"Strategies to reduce or contain expenses, including fixed and variable cost management, cost centres and expense minimisation."},
{id:"fi-fixed-costs", term:"Fixed costs", topic:"Finance", sub:"Financial management strategies", def:"Costs that do not change with the level of output, such as rent and insurance."},
{id:"fi-variable-costs", term:"Variable costs", topic:"Finance", sub:"Financial management strategies", def:"Costs that change directly with the level of output, such as raw materials and piece-rate wages."},
{id:"fi-cost-centre", term:"Cost centre", topic:"Finance", sub:"Financial management strategies", def:"A department or activity to which costs can be directly allocated, allowing managers to be held accountable for the spending they control."},
{id:"fi-expense-minimisation", term:"Expense minimisation", topic:"Finance", sub:"Financial management strategies", def:"Reducing costs to their lowest sustainable level without compromising the quality of output."},
{id:"fi-revenue-controls", term:"Revenue controls", topic:"Finance", sub:"Financial management strategies", def:"Strategies focused on the income side of profitability, setting marketing objectives for sales mix, pricing and volume."},
{id:"fi-break-even", term:"Break-even point", topic:"Finance", sub:"Financial management strategies", def:"The level of sales at which total revenue equals total costs, so the business makes neither a profit nor a loss.", formula:"Break-even units = fixed costs ÷ (price − variable cost per unit)"},
{id:"fi-exchange-rate", term:"Exchange rate", topic:"Finance", sub:"Financial management strategies", def:"The price of one currency in terms of another. Movements change the Australian dollar value of overseas receipts and payments."},
{id:"fi-appreciation", term:"Appreciation", topic:"Finance", sub:"Financial management strategies", def:"A rise in the value of the Australian dollar, which makes imports cheaper and exports dearer to overseas buyers."},
{id:"fi-depreciation-currency", term:"Depreciation (currency)", topic:"Finance", sub:"Financial management strategies", def:"A fall in the value of the Australian dollar, which raises the cost of imported inputs but makes exports more competitive."},
{id:"fi-payment-advance", term:"Payment in advance", topic:"Finance", sub:"Financial management strategies", def:"An international payment method where the importer pays before goods are shipped. Safest for the exporter, riskiest for the importer."},
{id:"fi-letter-credit", term:"Letter of credit", topic:"Finance", sub:"Financial management strategies", def:"A bank's undertaking to pay the exporter once specified shipping documents are presented, which removes most risk for both parties."},
{id:"fi-clean-payment", term:"Clean payment", topic:"Finance", sub:"Financial management strategies", def:"An international payment made after the goods have been shipped, relying entirely on trust between the parties."},
{id:"fi-bill-exchange", term:"Bill of exchange", topic:"Finance", sub:"Financial management strategies", def:"A document ordering the importer to pay a set amount on a set date, allowing the exporter to be paid while offering the importer credit."},
{id:"fi-hedging", term:"Hedging", topic:"Finance", sub:"Financial management strategies", def:"Taking action to minimise the risk of adverse exchange rate movements, so the domestic value of a future foreign transaction is protected."},
{id:"fi-derivatives", term:"Derivatives", topic:"Finance", sub:"Financial management strategies", def:"Financial instruments whose value derives from an underlying asset, used to hedge against price or currency movements.", eg:"Futures, options and swaps."},
{id:"fi-natural-hedging", term:"Natural hedging", topic:"Finance", sub:"Financial management strategies", def:"Offsetting foreign currency receipts against foreign currency payments in the same currency, so exposure cancels out without buying a derivative."},

// ================= HUMAN RESOURCES =================
// --- Role of human resource management ---
{id:"hr-hrm", term:"Human resource management", topic:"Human Resources", sub:"Role of human resource management", def:"The management of the total relationship between an employer and employee, from attracting staff through to their eventual separation."},
{id:"hr-strategic-role", term:"Strategic role of human resources", topic:"Human Resources", sub:"Role of human resource management", def:"Aligning the management of people with the long-term goals of the business, treating staff as an asset that creates competitive advantage."},
{id:"hr-outsourcing-hr", term:"Outsourcing (HR functions)", topic:"Human Resources", sub:"Role of human resource management", def:"Contracting an external provider to carry out human resource activities such as payroll, recruitment or training."},
{id:"hr-contractors", term:"Contractors", topic:"Human Resources", sub:"Role of human resource management", def:"Workers engaged for a specific task or period who are not employees, giving the business flexibility without ongoing employment obligations."},
{id:"hr-domestic-contractor", term:"Domestic contractors", topic:"Human Resources", sub:"Role of human resource management", def:"Contractors engaged within Australia, subject to Australian law and easier to supervise than offshore providers."},
{id:"hr-global-contractor", term:"Global contractors", topic:"Human Resources", sub:"Role of human resource management", def:"Contractors engaged overseas, usually to access lower labour costs or skills unavailable locally, at the cost of control and cultural distance."},

// --- Key influences ---
{id:"hr-stakeholders", term:"Stakeholders (HR)", topic:"Human Resources", sub:"Key influences", def:"The groups with an interest in how a business manages its people: employers, employees, employer associations, unions, government organisations and society."},
{id:"hr-employer-assoc", term:"Employer associations", topic:"Human Resources", sub:"Key influences", def:"Bodies that advise and represent employers in industrial matters, including in negotiations and before tribunals."},
{id:"hr-unions", term:"Trade unions", topic:"Human Resources", sub:"Key influences", def:"Organisations formed to represent and advance the interests of employees, particularly over pay and conditions."},
{id:"hr-fair-work", term:"Fair Work Commission", topic:"Human Resources", sub:"Key influences", def:"Australia's national workplace relations tribunal, which sets minimum wages, approves agreements and resolves disputes."},
{id:"hr-common-law", term:"Common law (employment)", topic:"Human Resources", sub:"Key influences", def:"Judge-made law setting out the implied rights and obligations of employers and employees, such as the duty of care and the duty to obey lawful instructions."},
{id:"hr-nes", term:"Minimum employment standards", topic:"Human Resources", sub:"Key influences", def:"The legislated conditions that apply to all employees regardless of any agreement, covering hours, leave, notice and flexible work requests."},
{id:"hr-minimum-wage", term:"Minimum wage", topic:"Human Resources", sub:"Key influences", def:"The lowest rate of pay an employer may lawfully pay, reviewed annually by the national workplace tribunal."},
{id:"hr-award", term:"Award", topic:"Human Resources", sub:"Key influences", def:"A legally binding document setting out minimum pay and conditions for an entire industry or occupation."},
{id:"hr-enterprise-agreement", term:"Enterprise agreement", topic:"Human Resources", sub:"Key influences", def:"A collective agreement negotiated at the workplace between an employer and its employees, which must leave staff better off overall than the relevant award."},
{id:"hr-boott", term:"Better off overall test", topic:"Human Resources", sub:"Key influences", def:"The test an enterprise agreement must pass before approval: every employee must be better off overall than under the applicable award."},
{id:"hr-employment-contract", term:"Employment contract", topic:"Human Resources", sub:"Key influences", def:"A legally binding agreement between employer and employee setting out the terms of the working relationship."},
{id:"hr-whs", term:"Work health and safety", topic:"Human Resources", sub:"Key influences", def:"The legal duty on employers to provide a workplace free of foreseeable risk to health and safety, so far as is reasonably practicable."},
{id:"hr-workers-comp", term:"Workers compensation", topic:"Human Resources", sub:"Key influences", def:"A compulsory insurance scheme providing income and medical costs to employees injured at work, regardless of who was at fault."},
{id:"hr-antidiscrimination", term:"Antidiscrimination", topic:"Human Resources", sub:"Key influences", def:"Laws prohibiting less favourable treatment of a person on the basis of an attribute such as sex, race, age or disability."},
{id:"hr-eeo", term:"Equal employment opportunity", topic:"Human Resources", sub:"Key influences", def:"Policies ensuring all employees have an equal chance of being hired, trained and promoted on merit."},
{id:"hr-economic-influence", term:"Economic influences (HR)", topic:"Human Resources", sub:"Key influences", def:"The effect of the business cycle on staffing: expansion drives recruitment and wage pressure, downturn drives redundancy and casualisation."},
{id:"hr-technological-influence", term:"Technological influences (HR)", topic:"Human Resources", sub:"Key influences", def:"The effect of technology on the workforce — changing the skills required, enabling remote work, and displacing routine roles."},
{id:"hr-work-patterns", term:"Changing work patterns", topic:"Human Resources", sub:"Key influences", def:"Shifts in how and when people work, including growth in part-time, casual and remote work and in career mobility."},
{id:"hr-living-standards", term:"Living standards", topic:"Human Resources", sub:"Key influences", def:"The material and non-material wellbeing of employees, which employment conditions and wage levels directly shape."},
{id:"hr-ethics-csr", term:"Ethics and CSR (HR)", topic:"Human Resources", sub:"Key influences", def:"Managing people beyond the legal minimum — fair pay, safe conditions, genuine consultation and respect for work-life balance."},
{id:"hr-workforce-diversity", term:"Workforce diversity", topic:"Human Resources", sub:"Key influences", def:"Differences among employees in age, gender, ethnicity, ability and background, which broaden the skills and perspectives available to the business."},

// --- Processes of human resource management ---
{id:"hr-acquisition", term:"Acquisition", topic:"Human Resources", sub:"Processes of human resource management", def:"The process of attracting and hiring staff with the right skills, covering job analysis, recruitment, selection and employment arrangements."},
{id:"hr-development", term:"Development (HR process)", topic:"Human Resources", sub:"Processes of human resource management", def:"Building the competence and career capability of employees over time through training, mentoring and planned experience."},
{id:"hr-maintenance", term:"Maintenance", topic:"Human Resources", sub:"Processes of human resource management", def:"Retaining and motivating existing staff by managing pay, conditions, safety, communication and compliance with legal obligations."},
{id:"hr-separation", term:"Separation", topic:"Human Resources", sub:"Processes of human resource management", def:"The ending of the employment relationship, whether voluntary (resignation, retirement) or involuntary (redundancy, dismissal)."},
{id:"hr-job-analysis", term:"Job analysis", topic:"Human Resources", sub:"Processes of human resource management", def:"Systematically studying a job to determine its duties and the skills, knowledge and attributes needed to perform it."},
{id:"hr-voluntary-separation", term:"Voluntary separation", topic:"Human Resources", sub:"Processes of human resource management", def:"Separation initiated by the employee, such as resignation, voluntary redundancy or retirement."},
{id:"hr-involuntary-separation", term:"Involuntary separation", topic:"Human Resources", sub:"Processes of human resource management", def:"Separation initiated by the employer, such as retrenchment, dismissal for misconduct, or termination for poor performance."},
{id:"hr-unfair-dismissal", term:"Unfair dismissal", topic:"Human Resources", sub:"Processes of human resource management", def:"Termination that is harsh, unjust or unreasonable, for which an employee may seek reinstatement or compensation."},

// --- Human resource strategies ---
{id:"hr-leadership-style", term:"Leadership style", topic:"Human Resources", sub:"Human resource strategies", def:"The way a manager exercises authority and relates to staff, ranging from autocratic through participative to laissez-faire."},
{id:"hr-job-design", term:"Job design", topic:"Human Resources", sub:"Human resource strategies", def:"Deciding the number and nature of tasks in a job, on a spectrum from narrow, specific tasks to broad, general responsibilities."},
{id:"hr-job-enlargement", term:"Job enlargement", topic:"Human Resources", sub:"Human resource strategies", def:"Widening a job by adding tasks at the same level of responsibility, to reduce monotony."},
{id:"hr-job-enrichment", term:"Job enrichment", topic:"Human Resources", sub:"Human resource strategies", def:"Deepening a job by adding responsibility, autonomy and decision-making, to raise motivation."},
{id:"hr-job-rotation", term:"Job rotation", topic:"Human Resources", sub:"Human resource strategies", def:"Moving employees between different jobs to broaden their skills and relieve boredom."},
{id:"hr-recruitment", term:"Recruitment", topic:"Human Resources", sub:"Human resource strategies", def:"Attracting a pool of suitably qualified applicants for a position, from internal or external sources."},
{id:"hr-internal-recruitment", term:"Internal recruitment", topic:"Human Resources", sub:"Human resource strategies", def:"Filling a vacancy from existing staff. It is cheaper, faster and motivating, but brings no fresh perspective."},
{id:"hr-external-recruitment", term:"External recruitment", topic:"Human Resources", sub:"Human resource strategies", def:"Filling a vacancy from outside the business. It brings new skills and ideas but costs more and carries greater uncertainty."},
{id:"hr-training", term:"Training", topic:"Human Resources", sub:"Human resource strategies", def:"Teaching employees the skills needed to perform their current job to standard."},
{id:"hr-development-strategy", term:"Development (HR strategy)", topic:"Human Resources", sub:"Human resource strategies", def:"Preparing employees for future roles and responsibilities rather than their present job, building the business's long-term capability."},
{id:"hr-induction", term:"Induction", topic:"Human Resources", sub:"Human resource strategies", def:"The structured introduction of a new employee to the business, its culture, systems and safety requirements."},
{id:"hr-performance-mgmt", term:"Performance management", topic:"Human Resources", sub:"Human resource strategies", def:"Systematically assessing employee performance against agreed standards, for either developmental or administrative purposes."},
{id:"hr-developmental-appraisal", term:"Developmental performance management", topic:"Human Resources", sub:"Human resource strategies", def:"Appraisal aimed at improving the employee's future performance through feedback, coaching and goal setting."},
{id:"hr-administrative-appraisal", term:"Administrative performance management", topic:"Human Resources", sub:"Human resource strategies", def:"Appraisal used to make decisions about pay, promotion, transfer or termination."},
{id:"hr-360-feedback", term:"360-degree feedback", topic:"Human Resources", sub:"Human resource strategies", def:"Performance appraisal drawing on input from supervisors, peers, subordinates and sometimes customers, to reduce single-rater bias."},
{id:"hr-rewards", term:"Rewards", topic:"Human Resources", sub:"Human resource strategies", def:"The monetary and non-monetary benefits given to employees in return for their contribution, offered individually or to a group."},
{id:"hr-monetary-rewards", term:"Monetary rewards", topic:"Human Resources", sub:"Human resource strategies", def:"Financial benefits such as wages, salaries, bonuses, share plans and superannuation above the compulsory rate."},
{id:"hr-nonmonetary-rewards", term:"Non-monetary rewards", topic:"Human Resources", sub:"Human resource strategies", def:"Benefits with value that is not cash, such as flexible hours, additional leave, a company car, recognition or career development."},
{id:"hr-performance-pay", term:"Performance pay", topic:"Human Resources", sub:"Human resource strategies", def:"Payment linked directly to measured results rather than time worked, intended to align employee effort with business objectives."},
{id:"hr-global-costs", term:"Global HR — costs", topic:"Human Resources", sub:"Human resource strategies", def:"Managing labour cost differences across countries, which drives decisions to offshore production or service functions."},
{id:"hr-global-skills", term:"Global HR — skills", topic:"Human Resources", sub:"Human resource strategies", def:"Sourcing capabilities internationally where the required skills are scarce or cheaper to obtain overseas."},
{id:"hr-global-supply", term:"Global HR — supply", topic:"Human Resources", sub:"Human resource strategies", def:"Managing the availability of labour in each market, including skills shortages, migration rules and local employment law."},
{id:"hr-workplace-dispute", term:"Workplace dispute", topic:"Human Resources", sub:"Human resource strategies", def:"A disagreement between employer and employees over pay, conditions or management decisions, which may lead to industrial action."},
{id:"hr-negotiation", term:"Negotiation", topic:"Human Resources", sub:"Human resource strategies", def:"Direct discussion between the parties to a dispute aimed at reaching an agreement without outside involvement."},
{id:"hr-mediation", term:"Mediation", topic:"Human Resources", sub:"Human resource strategies", def:"Dispute resolution in which an impartial third party helps the parties reach their own agreement, without imposing a decision."},
{id:"hr-conciliation", term:"Conciliation", topic:"Human Resources", sub:"Human resource strategies", def:"Dispute resolution in which a third party actively suggests options and guides the parties towards a settlement they agree to."},
{id:"hr-arbitration", term:"Arbitration", topic:"Human Resources", sub:"Human resource strategies", def:"Dispute resolution in which an independent tribunal hears both sides and hands down a legally binding decision."},
{id:"hr-grievance-procedure", term:"Grievance procedure", topic:"Human Resources", sub:"Human resource strategies", def:"A formal, documented process for raising and resolving employee complaints, resolving most disputes before they escalate."},
{id:"hr-industrial-action", term:"Industrial action", topic:"Human Resources", sub:"Human resource strategies", def:"Action taken by employees (strikes, work bans) or employers (lockouts) to apply pressure during a dispute."},

// --- Effectiveness of human resource management ---
{id:"hr-corporate-culture", term:"Corporate culture", topic:"Human Resources", sub:"Effectiveness of human resource management", def:"The shared values, beliefs and practices of the people in a business — an indicator of HR effectiveness because a strong culture retains and motivates staff."},
{id:"hr-benchmarking", term:"Benchmarking", topic:"Human Resources", sub:"Effectiveness of human resource management", def:"Comparing a business's HR performance against a standard or against best practice elsewhere, to identify where it is falling short."},
{id:"hr-staff-turnover", term:"Staff turnover", topic:"Human Resources", sub:"Effectiveness of human resource management", def:"The rate at which employees leave and are replaced. High turnover signals dissatisfaction and imposes recruitment and training costs.", formula:"Turnover rate = separations ÷ average number of employees × 100"},
{id:"hr-absenteeism", term:"Absenteeism", topic:"Human Resources", sub:"Effectiveness of human resource management", def:"The frequency of unscheduled employee absence, used as an indicator of morale, workload and workplace health."},
{id:"hr-accidents", term:"Accidents (as an indicator)", topic:"Human Resources", sub:"Effectiveness of human resource management", def:"The number and severity of workplace injuries, which measures both the safety of the workplace and the effectiveness of training."},
{id:"hr-disputation", term:"Levels of disputation", topic:"Human Resources", sub:"Effectiveness of human resource management", def:"The number of disputes and working days lost to industrial action, indicating the health of the employer-employee relationship."},
{id:"hr-worker-satisfaction", term:"Worker satisfaction", topic:"Human Resources", sub:"Effectiveness of human resource management", def:"How content employees are with their work, pay and conditions, commonly measured through surveys, exit interviews and retention rates."},
{id:"hr-productivity", term:"Labour productivity", topic:"Human Resources", sub:"Effectiveness of human resource management", def:"Output produced per unit of labour input. Rising productivity indicates that HR strategies are translating into performance.", formula:"Labour productivity = total output ÷ labour hours"},
];
